#include "squeeze_net_fire_module_custom_tiling.h"
#include "register/op_def_registry.h"

namespace optiling {
const uint32_t BLOCK_DIM = 8;
const uint32_t TILE_NUM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    SqueezeNetFireModuleCustomTilingData tiling;

    const gert::Shape* x_shape = context->GetInputShape(0);
    const gert::Shape* sq_w_shape = context->GetInputShape(1);
    const gert::Shape* e1_w_shape = context->GetInputShape(3);
    const gert::Shape* e3_w_shape = context->GetInputShape(5);

    // 假定输入为 [N, C, H, W]，权重为 [Cout, Cin, KH, KW]
    uint32_t n = static_cast<uint32_t>(x_shape->GetOriginShape().GetDim(0));
    uint32_t c_in = static_cast<uint32_t>(x_shape->GetOriginShape().GetDim(1));
    uint32_t h = static_cast<uint32_t>(x_shape->GetOriginShape().GetDim(2));
    uint32_t w = static_cast<uint32_t>(x_shape->GetOriginShape().GetDim(3));

    uint32_t c_sq = static_cast<uint32_t>(sq_w_shape->GetOriginShape().GetDim(0));
    uint32_t c_e1 = static_cast<uint32_t>(e1_w_shape->GetOriginShape().GetDim(0));
    uint32_t c_e3 = static_cast<uint32_t>(e3_w_shape->GetOriginShape().GetDim(0));

    uint32_t out_c = c_e1 + c_e3;
    uint32_t out_elements = n * out_c * h * w;

    context->SetBlockDim(BLOCK_DIM);

    tiling.set_n(n);
    tiling.set_c_in(c_in);
    tiling.set_h(h);
    tiling.set_w(w);
    tiling.set_c_sq(c_sq);
    tiling.set_c_e1(c_e1);
    tiling.set_c_e3(c_e3);
    tiling.set_tileNum(TILE_NUM);
    tiling.set_out_elements(out_elements);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t* ws = context->GetWorkspaceSizes(1);
    ws[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

